package android.content.pm; public class PackageManager { public static class NameNotFoundException extends Exception {} public PermissionInfo getPermissionInfo(String n,int f)throws NameNotFoundException {if(n.startsWith("custom"))throw new NameNotFoundException();PermissionInfo i=new PermissionInfo();i.name=n;i.protectionLevel=n.contains("CAMERA")?1:0;return i;} public ApplicationInfo getApplicationInfo(String n,int f)throws NameNotFoundException{return new ApplicationInfo();} }